package com.opensocket.aievent.core.action.executor.issue.scoped;
import com.opensocket.aievent.core.integration.identity.*; import java.net.URLEncoder; import java.nio.charset.StandardCharsets; import java.util.*; import tools.jackson.databind.ObjectMapper;
final class JiraPermissionProbeAdapter {
 private final ScopedProviderHttpSupport http; JiraPermissionProbeAdapter(ObjectMapper json){http=new ScopedProviderHttpSupport(json);}
 PermissionProbeObservation probe(IntegrationConnection c,IntegrationPrincipal p,IntegrationCredentialMetadata credential,IntegrationProjectMapping mapping,String secret){var caps=blank();var elevated=new LinkedHashSet<String>();try{var headers=http.authHeaders(p,credential,secret);var me=http.get(ScopedProviderHttpSupport.join(c.baseUrl(),"/rest/api/3/myself"),headers,c.timeoutMs());if(me.statusCode()==401||me.statusCode()==403){denyAll(caps);return new PermissionProbeObservation(caps,List.of(),"Jira authentication was rejected with "+me.statusCode()+".");}caps.put(IntegrationPermissionCapability.AUTHENTICATE,ScopedProviderHttpSupport.ok(me.statusCode())?PermissionProbeResultStatus.GRANTED:PermissionProbeResultStatus.ERROR);elevated.addAll(ScopedProviderHttpSupport.headerSet(me,"X-OpenDispatch-Elevated-Permissions"));if(mapping==null)return new PermissionProbeObservation(caps,List.copyOf(elevated),"Authentication was probed without a Project Mapping.");String project=first(mapping.externalProjectKey(),mapping.externalProjectId());var projectResponse=http.get(ScopedProviderHttpSupport.join(c.baseUrl(),"/rest/api/3/project/"+URLEncoder.encode(project,StandardCharsets.UTF_8)),headers,c.timeoutMs());caps.put(IntegrationPermissionCapability.PROJECT_VISIBLE,ScopedProviderHttpSupport.ok(projectResponse.statusCode())?PermissionProbeResultStatus.GRANTED:PermissionProbeResultStatus.DENIED);String permissions="BROWSE_PROJECTS,CREATE_ISSUES,ADD_COMMENTS,EDIT_ISSUES,LINK_ISSUES,ADMINISTER";var permissionResponse=http.get(ScopedProviderHttpSupport.join(c.baseUrl(),"/rest/api/3/mypermissions?projectKey="+URLEncoder.encode(project,StandardCharsets.UTF_8)+"&permissions="+permissions),headers,c.timeoutMs());if(ScopedProviderHttpSupport.ok(permissionResponse.statusCode())){var parsed=http.parse(permissionResponse.body());Object node=parsed.get("permissions");if(node instanceof Map<?,?> map){set(caps,map,"BROWSE_PROJECTS",IntegrationPermissionCapability.READ_ISSUE);set(caps,map,"CREATE_ISSUES",IntegrationPermissionCapability.CREATE_ISSUE);set(caps,map,"ADD_COMMENTS",IntegrationPermissionCapability.ADD_COMMENT);set(caps,map,"EDIT_ISSUES",IntegrationPermissionCapability.UPDATE_ISSUE);set(caps,map,"LINK_ISSUES",IntegrationPermissionCapability.CREATE_RELATION);if(granted(map,"ADMINISTER"))elevated.add("PROVIDER_ADMINISTRATOR");}}else if(permissionResponse.statusCode()==401||permissionResponse.statusCode()==403){caps.replaceAll((k,v)->v==PermissionProbeResultStatus.NOT_TESTED?PermissionProbeResultStatus.DENIED:v);}caps.put(IntegrationPermissionCapability.OBSERVE_STATUS,caps.get(IntegrationPermissionCapability.READ_ISSUE));caps.put(IntegrationPermissionCapability.READ_ATTACHMENT_METADATA,caps.get(IntegrationPermissionCapability.READ_ISSUE));return new PermissionProbeObservation(caps,List.copyOf(elevated),"Jira Project permissions were probed through the scoped mypermissions endpoint.");}catch(Exception e){caps.replaceAll((k,v)->v==PermissionProbeResultStatus.NOT_TESTED?PermissionProbeResultStatus.ERROR:v);return new PermissionProbeObservation(caps,List.copyOf(elevated),"Jira Permission Probe failed: "+e.getClass().getSimpleName());}}
 private EnumMap<IntegrationPermissionCapability,PermissionProbeResultStatus> blank(){var m=new EnumMap<IntegrationPermissionCapability,PermissionProbeResultStatus>(IntegrationPermissionCapability.class);for(var c:IntegrationPermissionCapability.values())m.put(c,PermissionProbeResultStatus.NOT_TESTED);return m;} private void denyAll(Map<IntegrationPermissionCapability,PermissionProbeResultStatus> m){m.replaceAll((k,v)->PermissionProbeResultStatus.DENIED);} private void set(Map<IntegrationPermissionCapability,PermissionProbeResultStatus> out,Map<?,?> map,String key,IntegrationPermissionCapability capability){out.put(capability,granted(map,key)?PermissionProbeResultStatus.GRANTED:PermissionProbeResultStatus.DENIED);} private boolean granted(Map<?,?> map,String key){Object v=map.get(key);if(v instanceof Map<?,?> node)return Boolean.TRUE.equals(node.get("havePermission"));return false;} private String first(String a,String b){return a!=null&&!a.isBlank()?a:b;}
}
